class Solution {
public:
    int findMinMoves(vector<int>& machines) {
        int n = machines.size();
        long long sum = 0;
        for (int i = 0; i < n; i++) sum += machines[i];
        if (sum % n != 0) return -1;
        long long target = sum / n;
        long long prefix = 0;
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            prefix += (long long)machines[i] - target;
            long long give = (long long)machines[i] - target;
            if (give < 0) give = 0;
            long long absPrefix = prefix < 0 ? -prefix : prefix;
            long long cur = absPrefix > give ? absPrefix : give;
            if (cur > ans) ans = cur;
        }
        return (int)ans;
    }
};
